class Solution {
public:
    int maxRemoval(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        sort(queries.begin(), queries.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });

        priority_queue<int> available;
        vector<int> diff(n + 1, 0);
        int currCoverage = 0;
        int qIdx = 0;
        int used = 0;

        for (int i = 0; i < n; ++i) {
            currCoverage += diff[i];
            while (qIdx < (int)queries.size() && queries[qIdx][0] == i) {
                available.push(queries[qIdx][1]);
                qIdx++;
            }
            while (currCoverage < nums[i]) {
                if (available.empty() || available.top() < i) return -1;
                int r = available.top();
                available.pop();
                currCoverage++;
                diff[r + 1]--;
                used++;
            }
        }
        return queries.size() - used;
    }
};

class Solution {
    public int maxRemoval(int[] nums, int[][] queries) {
        int n = nums.length;
        Arrays.sort(queries, (a, b) -> Integer.compare(a[0], b[0]));

        PriorityQueue<Integer> available = new PriorityQueue<>(Collections.reverseOrder());
        int[] diff = new int[n + 1];
        int currCoverage = 0;
        int qIdx = 0;
        int used = 0;

        for (int i = 0; i < n; ++i) {
            currCoverage += diff[i];
            while (qIdx < queries.length && queries[qIdx][0] == i) {
                available.offer(queries[qIdx][1]);
                qIdx++;
            }
            while (currCoverage < nums[i]) {
                if (available.isEmpty() || available.peek() < i) return -1;
                int r = available.poll();
                currCoverage++;
                diff[r + 1]--;
                used++;
            }
        }
        return queries.length - used;
    }
}

var maxRemoval = function(nums, queries) {
    const n = nums.length;
    queries.sort((a, b) => a[0] - b[0]);

    // Simple max priority queue simulation via sorted array or binary heap
    const available = [];
    const diff = new Int32Array(n + 1);
    let currCoverage = 0;
    let qIdx = 0;
    let used = 0;

    const pushHeap = (val) => {
        let l = 0, r = available.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (available[mid] < val) l = mid + 1;
            else r = mid;
        }
        available.splice(l, 0, val);
    };

    for (let i = 0; i < n; i++) {
        currCoverage += diff[i];
        while (qIdx < queries.length && queries[qIdx][0] === i) {
            pushHeap(queries[qIdx][1]);
            qIdx++;
        }
        while (currCoverage < nums[i]) {
            if (available.length === 0 || available[available.length - 1] < i) return -1;
            const r = available.pop();
            currCoverage++;
            diff[r + 1]--;
            used++;
        }
    }
    return queries.length - used;
};
